t\"}],[\"$\",\"ul\",null,{\"className\":\"mt-2 list-disc space-y-1.5 pl-5\",\"children\":[[\"$\",\"li\",\"A portfolio, product page or blog post needs an image gallery that opens photos full screen without losing the sense of where they came from.\",{\"children\":\"A portfolio, product page or blog post needs an image gallery that opens photos full screen without losing the sense of where they came from.\"}],[\"$\",\"li\",\"A chat or ticketing app shows attachment previews that should expand into a zoomable viewer.\",{\"children\":\"A chat or ticketing app shows attachment previews that should expand into a zoomable viewer.\"}],[\"$\",\"li\",\"A real estate, travel or ecommerce listing needs swipeable full-size photos on mobile with captions and a counter.\",{\"children\":\"A real estate, travel or ecommerce listing needs swipeable full-size photos on mobile with captions and a counter.\"}]]}],[\"$\",\"h3\",null,{\"className\":\"mt-6 font-medium text-foreground\",\"children\":\"Accessibility\"}],[\"$\",\"p\",null,{\"className\":\"mt-2\",\"children\":\"Thumbnails are buttons labelled \\\"Open\\\" plus the image alt text, with aria-haspopup and aria-expanded. The viewer is a modal dialog rendered in a portal: focus moves inside, Tab is trapped, the rest of the page becomes inert and scroll-locked, Escape closes it, and focus returns to the thumbnail. Arrow Left and Arrow Right page between images, the zoom toggle reports its pressed state and pans with arrow keys while zoomed, and the counter and caption are polite live regions. With reduced motion enabled, the thumbnail morph is dropped and images change with a short fade instead of sliding.\"}],[\"$\",\"h3\",null,{\"className\":\"mt-6 font-medium text-foreground\",\"children\":\"FAQ\"}],[\"$\",\"dl\",null,{\"className\":\"mt-2 space-y-4\",\"children\":[[\"$\",\"div\",\"How do I make an image lightbox gallery in React?\",{\"children\":[[\"$\",\"dt\",null,{\"className\":\"font-medium text-foreground\",\"children\":\"How do I make an image lightbox gallery in React?\"}],[\"$\",\"dd\",null,{\"className\":\"mt-1\",\"children\":\"Install the component and pass an images array to ImageViewer, where each image has id, src, alt, width and height. The default layout renders a thumbnail grid and the viewer, so no other setup is needed.\"}]]}],[\"$\",\"div\",\"Can I control which image is open?\",{\"children\":[[\"$\",\"dt\",null,{\"className\":\"font-medium text-foreground\",\"children\":\"Can I control which image is open?\"}],[\"$\",\"dd\",null,{\"className\":\"mt-1\",\"children\":\"Yes. Pass value and onValueChange to control the open image id, or defaultValue for uncontrolled use. A value of null means the viewer is closed.\"}]]}],[\"$\",\"div\",\"Can I customize the thumbnails and viewer controls?\",{\"children\":[\"$L34\",\"$L35\"]}]]}]]}]]}]}]\n2a:[\"$\",\"p\",null,{\"className\":\"mt-6 text-xs text-muted-foreground\",\"children\":[\"Updated\",\" \",[\"$\",\"time\",null,{\"dateTime\":\"2026-10-23\",\"children\":\"Oct 23, 2026\"}]]}]\n34:[\"$\",\"dt\",null,{\"className\":\"font-medium text-foreground\",\"children\":\"Can I customize the thumbnails and viewer controls?\"}]\n35:[\"$\",\"dd\",null,{\"className\":\"mt-1\",\"children\":\"Pass children to ImageViewer and compose ImageViewerGallery, ImageViewerThumbnail, ImageViewerContent, ImageViewerCaption, ImageViewerCounter, ImageViewerPrevious, ImageViewerNext and ImageViewerClose yourself, or build custom controls with useImageViewer. It uses plain img elements, so it works in Next.js and outside it.\"}]\n36:I[557434,[\"/_next/static/chunks/33t46atd3n2zd.js\",\"/_next/static/chunks/21lteqi1xna8r.js\",\"/_next/static/chunks/1kg4uo19j3nyn.js\",\"/_next/static/chunks/1p-em3jtknkl7.js\",\"/_next/static/chunks/26h16sd2et6nm.js\",\"/_next/static/chunks/42bb_8q-n9zu0.js\",\"/_next/static/chunks/1s9hhbjh-20mj.js\",\"/_next/static/chunks/12-pdpu_u49xd.js\",\"/_next/static/chunks/0tjcxouu9yygq.js\",\"/_next/static/chunks/3wlpm7z824n71.js\",\