idth={image.width}\n                      height={image.height}\n                      draggable={false}\n                      onError={() =\u003e {\n                        if (slidePresent \u0026\u0026 present) setFailed(true);\n                      }}\n                      // Keep Motion's drag/layout registration mounted across zoom changes.\n                      drag\n                      dragListener={zoom}\n                      dragConstraints={{\n                        left: -pan.x,\n                        right: pan.x,\n                        top: -pan.y,\n                        bottom: pan.y,\n                      }}\n                      dragElastic={0.08}\n                      dragMomentum={false}\n                      animate={{\n                        scale: zoom \u0026\u0026 present ? 2 : 1,\n                        ...(!present ? { x: 0, y: 0 } : {}),\n                      }}\n                      transition={reduce ? { duration: 0 } : SPRING_LAYOUT}\n                      onPointerDown={(event) =\u003e {\n                        // Swiping the image keeps keyboard focus on the controls.\n                        event.preventDefault();\n                        if (!zoom \u0026\u0026 event.isPrimary)\n                          swipe.current = {\n                            x: event.clientX,\n                            y: event.clientY,\n                          };\n                      }}\n                      onPointerUp={(event) =\u003e {\n                        const start = swipe.current;\n                        swipe.current = null;\n                        if (!start || zoom) return;\n                        const dx = event.clientX - start.x;\n                        const dy = event.clientY - start.y;\n                        if (\n                          Math.abs(dx) \u003e 50 \u0026\u0026\n                          Math.abs(dx) \u003e Math.abs(dy) * 1.5\n                        )\n                          onSwipe(dx