  }),
  exit: ({ direction, reduce }: ImageSwap) => ({
    opacity: reduce ? 0 : 1,
    x: `${reduce ? 0 : direction * -100}%`,
    transition: reduce
      ? { duration: 0.1, ease: EASE_OUT }
      : IMAGE_SLIDE_TRANSITION,
  }),
